    bool has_background_color;
    uint32_t background_color; /* @0x8 uint32_t, has_ @0x7. entry +0xAB has-flag, +0xAC: colour of background mode 2; packed colour decoded by rgb_unpack_color: bit 31 clear = RGB565 in bits 15:0, bit 31 set = RGB888 in bits 23:0 with a 7-bit alpha in bits 30:24 */
