    uint32_t color; /* @0xC uint32_t. entry +0xB0: colour of the lit LEDs, end colour of the gradient; packed colour decoded by rgb_unpack_color: bit 31 clear = RGB565 in bits 15:0, bit 31 set = RGB888 in bits 23:0 with a 7-bit alpha in bits 30:24 */
    bool has_background_color;
    uint32_t background_color; /* @0x14 uint32_t, has_ @0x10. entry +0xB4 has-flag, +0xB8: colour of the unlit LEDs; absent = unlit LEDs keep the frame colour; packed colour */
    pb_size_t which_target;
    union {
        LightbarRange range; /* @0x1A LightbarRange, 2 bytes, which_ @0x18. which_target == 5: light-bar range */
        KeyRect rect; /* @0x1A KeyRect, 4 bytes, which_ @0x18. which_target == 6: accepted by the schema, but the painter returns without drawing */
    } target;
    bool has_reverse;
    bool reverse; /* @0x1F bool, has_ @0x1E. entry +0xC2 has-flag, +0xC3: true = fill from the last position downwards */
