        RgbLegacyEffect legacy_effect; /* @0x20 RgbLegacyEffect, 8 bytes, which_ @0x1C. which_effect == 3: single effect in the old format; rgb_settings_convert_legacy_effect rewrites it in place into a one-entry layer list (tag 4) */
